// Generates src/print/printCss.generated.ts from the shared style sources.
//
// The print renderer needs the content CSS as a runtime string in both tsup (browser/Node
// bundles, no CSS loader) and vitest. The single source stays `src/styles/content.css` (+ the
// light `:root` tokens from `src/styles/tokens.css`); this script copies them verbatim into a
// TS module — never edit the generated file, and never duplicate a rule by hand.
import { readFileSync, writeFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const root = join(dirname(fileURLToPath(import.meta.url)), '..');
const tokensCss = readFileSync(join(root, 'src/styles/tokens.css'), 'utf8');
const contentCss = readFileSync(join(root, 'src/styles/content.css'), 'utf8');

// Light theme only: dark-mode overrides stay out of print.
const light = /:root\s*\{[^}]*\}/.exec(tokensCss)?.[0];
if (!light) throw new Error('gen-print-css: no :root block in src/styles/tokens.css');
if (/@import/i.test(contentCss) || /<link/i.test(contentCss))
  throw new Error('gen-print-css: content.css must not reference external sheets');
const ts = (css) => css.replace(/\\/g, '\\\\').replace(/`/g, '\\`').replace(/\${/g, '\\${');

const out = `// GENERATED by scripts/gen-print-css.mjs — do not edit. Source: src/styles/tokens.css
// (:root) + src/styles/content.css. Regenerate with \`npm run gen:print-css\`.
export const PRINT_TOKENS_CSS = \`${ts(light)}\`;
export const PRINT_CONTENT_CSS = \`${ts(contentCss)}\`;
`;
writeFileSync(join(root, 'src/print/printCss.generated.ts'), out);
console.log('gen-print-css: wrote src/print/printCss.generated.ts');
